package com.mavric.healthsqlserver;

import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.boot.context.properties.bind.*;
import org.springframework.boot.context.properties.source.MapConfigurationPropertySource;
import static org.junit.jupiter.api.Assertions.*;

class SqlServerRuntimePropertiesTest {
    static final String PREFIX="health.sqlserver.runtime",SECRET="synthetic-password-private-canary";
    static Map<String,Object> values(){var values=new LinkedHashMap<String,Object>();values.put(PREFIX+".server-name","synthetic.invalid");values.put(PREFIX+".database-name","Synthetic QA");values.put(PREFIX+".username","synthetic_runtime");values.put(PREFIX+".password",SECRET);return values;}
    static SqlServerRuntimeProperties bind(Map<String,Object> values){return new Binder(new MapConfigurationPropertySource(values)).bind(PREFIX,Bindable.of(SqlServerRuntimeProperties.class)).get();}
    static SqlServerRuntimeProperties props(String host,Integer port,String instance,String database,String user,String password,Boolean trust){return new SqlServerRuntimeProperties(host,port,instance,database,user,password,trust);}
    static void redacted(Throwable failure){var seen=Collections.newSetFromMap(new IdentityHashMap<Throwable,Boolean>());while(failure!=null && seen.add(failure)){assertFalse(Objects.toString(failure.getMessage(),"").contains(SECRET),"Secret in failure message");assertFalse(failure.toString().contains(SECRET),"Secret in failure rendering");failure=failure.getCause();}}
    @Test void defaultsAndExplicitPortTrustAndValuesRemainUnmodified(){var p=bind(values());assertEquals(1433,p.port());assertEquals(false,p.trustServerCertificate());assertNull(p.instanceName());assertEquals("synthetic.invalid",p.serverName());assertEquals("Synthetic QA",p.databaseName());assertEquals("synthetic_runtime",p.username());assertTrue(SECRET.equals(p.password()));var exact=props("(local)",65535,null," Database; preserved "," user ","  ",true);assertEquals(65535,exact.port());assertTrue(exact.trustServerCertificate());assertEquals(" Database; preserved ",exact.databaseName());assertEquals(" user ",exact.username());assertTrue("  ".equals(exact.password()));}
    @Test void namedInstanceDoesNotInventPortAndBindingRetainsEndpoint(){var values=values();values.put(PREFIX+".instance-name","SYNTHETIC_01");var p=bind(values);assertEquals("SYNTHETIC_01",p.instanceName());assertNull(p.port());values.put(PREFIX+".port",1433);redacted(assertThrows(RuntimeException.class,()->bind(values)));}
    @Test void safeHostAliasesAndIpEndpointsDoNotRequireResolution(){for(String host:List.of("synthetic.invalid","127.0.0.1","::1","[::1]",".","(local)","synthetic_alias-01"))assertEquals(host,props(host,null,null,"Synthetic","user",SECRET,null).serverName());for(String host:Arrays.asList(null,""," ","user@host","host;password=x","jdbc:sqlserver://host","host?query=x","host:1433","host\r\nInjected","host\u0000","host/path"))redacted(assertThrows(IllegalArgumentException.class,()->props(host,null,null,"Synthetic","user",SECRET,null)));}
    @Test void portAndInstanceRangesAndInjectionShapesFailWithoutValues(){for(Integer port:List.of(0,-1,65536,Integer.MAX_VALUE))redacted(assertThrows(IllegalArgumentException.class,()->props("synthetic",port,null,"Synthetic","user",SECRET,null)));for(int port:List.of(1,1433,65535))assertEquals(port,props("synthetic",port,null,"Synthetic","user",SECRET,null).port());for(String instance:List.of(""," ","unsafe;name","unsafe\nname","unsafe\\name","unsafe?name"))redacted(assertThrows(IllegalArgumentException.class,()->props("synthetic",null,instance,"Synthetic","user",SECRET,null)));}
    @Test void requiredDatabaseUsernamePasswordAndLengthsHaveSafeValidation(){for(String value:Arrays.asList(null,""," ","x".repeat(129),"bad\nvalue","bad\u0000value")){redacted(assertThrows(IllegalArgumentException.class,()->props("synthetic",null,null,value,"user",SECRET,null)));redacted(assertThrows(IllegalArgumentException.class,()->props("synthetic",null,null,"Synthetic",value,SECRET,null)));}for(String password:Arrays.asList(null,""))redacted(assertThrows(IllegalArgumentException.class,()->props("synthetic",null,null,"Synthetic","user",password,null)));assertEquals(128,props("synthetic",null,null,"x".repeat(128),"u".repeat(128),SECRET,null).databaseName().length());}
    @Test void constructorBindingFailuresAndConversionCausesNeverIncludePasswordCanary(){for(String field:List.of("server-name","database-name","username","password")){var values=values();values.remove(PREFIX+"."+field);redacted(assertThrows(RuntimeException.class,()->bind(values)));}for(var bad:List.of(Map.entry("port","not-an-integer"),Map.entry("trust-server-certificate","not-a-boolean"),Map.entry("database-name","x".repeat(129)),Map.entry("server-name","host;unsafe"))){var values=values();values.put(PREFIX+"."+bad.getKey(),bad.getValue());redacted(assertThrows(RuntimeException.class,()->bind(values)));}}
    @Test void toStringRedactsEveryFieldAndPropertiesCannotBeMutated(){var p=props("synthetic",null,"instance", "database","user",SECRET,true);assertEquals("SqlServerRuntimeProperties[redacted]",p.toString());for(String value:List.of("synthetic","instance","database","user",SECRET))assertFalse(p.toString().contains(value));for(var field:SqlServerRuntimeProperties.class.getDeclaredFields()){assertTrue(java.lang.reflect.Modifier.isPrivate(field.getModifiers()));assertTrue(java.lang.reflect.Modifier.isFinal(field.getModifiers()));}assertTrue(Arrays.stream(SqlServerRuntimeProperties.class.getMethods()).noneMatch(method->method.getName().startsWith("set")));}
}
